import {readFileSync,writeFileSync,mkdirSync,existsSync} from 'node:fs';
import {dirname,join} from 'node:path';
import {fileURLToPath} from 'node:url';
import {connectCDP,RecordingContext,Recorder,InteractionTimeline,compose,moveFileSync,pause} from '/Users/tanishqpalandurkar/.npm-global/lib/node_modules/@yyopc/yyoreel/dist/core/index.js';

const dir=dirname(fileURLToPath(import.meta.url));
const out='/Users/tanishqpalandurkar/Movies/clanker-two-user-2026-10-04';
const stopPath=join(dir,'stop-recording');
if(existsSync(stopPath))throw new Error('Remove previous stop signal only after reviewing previous capture.');
mkdirSync(out,{recursive:true});mkdirSync(join(out,'raw'),{recursive:true});
const slack=JSON.parse(readFileSync(join(dir,'browser.private.json'),'utf8'));
const workers=JSON.parse(readFileSync(join(dir,'worker-browsers.private.json'),'utf8'));
const tracks=[];
for(const a of slack.accounts)tracks.push({name:'slack-'+a.label.slice(-1),port:slack.port,targetId:a.targetId});
for(const w of workers.workers)tracks.push({name:'worker-'+w.key,port:w.port});
const width=1100,height=760,fps=10;
let stopping=false;
const metadata={pipeline:'yyoreel SDK 0.3.3 managed Chromium',out,width,height,fps,tracks:[]};
try{
  for(const t of tracks){
    const tabs=await(await fetch(`http://127.0.0.1:${t.port}/json/list`)).json();
    const tab=t.targetId?tabs.find(x=>x.id===t.targetId):tabs.find(x=>x.type==='page');
    if(!tab)throw new Error('Missing recording target '+t.name);
    t.client=await connectCDP(tab.webSocketDebuggerUrl);
    await t.client.Page.enable();await t.client.Runtime.enable();
    const loc=(await t.client.Runtime.evaluate({expression:'location.origin+location.pathname'})).result.value;
    if(t.name.startsWith('slack-')&&String(loc)!=='https://app.slack.com/client/T0C6J1XCDE0/C0C6J277ZNG')throw new Error('Slack not on the verified test channel: '+t.name);
    await t.client.Emulation.setDeviceMetricsOverride({width,height,deviceScaleFactor:1,mobile:false});
    t.ctx=new RecordingContext();t.ctx.setMode('record');
    t.timeline=new InteractionTimeline(width,height,{fps,zoom:1,autoZoom:false,background:'none',hud:{enabled:false},initialCursor:{x:-100,y:-100}});
    t.ctx.setTimeline(t.timeline);
    t.recorder=new Recorder(width,height,{fps,captureFormat:'png',preferScreenshots:true,crf:18});t.recorder.setTimeline(t.timeline);
    t.started_ns=process.hrtime.bigint().toString();t.started_utc=new Date().toISOString();
    await t.recorder.start(t.client,join(out,t.name+'.mp4'),t.ctx);
    metadata.tracks.push({name:t.name,started_utc:t.started_utc,started_monotonic_ns:t.started_ns});
  }
  metadata.ready_utc=new Date().toISOString();
  writeFileSync(join(dir,'capture-state.json'),JSON.stringify(metadata,null,2));
  console.log('ALL_FOUR_YYOREEL_RECORDERS_READY');
  const started=Date.now();
  while(!existsSync(stopPath)&&Date.now()-started<360000)await pause(500);
  stopping=true;
}finally{
  for(const t of tracks){
    if(t.recorder){
      await t.recorder.stop();
      const data=t.timeline.toJSON();const raw=join(out,'raw',t.name+'.mp4');
      moveFileSync(t.recorder.getTempVideoPath(),raw);
      writeFileSync(join(out,'raw',t.name+'.timeline.json'),JSON.stringify(data));
      const meta=metadata.tracks.find(m=>m.name===t.name);
      Object.assign(meta,{stopped_utc:new Date().toISOString(),frames:data.frames.length,encoded_seconds:data.frames.length/fps});
      await compose(raw,data,join(out,t.name+'.mp4'),{crf:18,preset:'veryfast'});
      console.log('TRACK_COMPOSED',t.name,data.frames.length);
    }
    if(t.client)await t.client.close();
  }
  metadata.stopped_by_signal=stopping;
  writeFileSync(join(out,'capture-metadata.json'),JSON.stringify(metadata,null,2));
  writeFileSync(join(dir,'capture-state.json'),JSON.stringify(metadata,null,2));
}
console.log('CAPTURE_COMPOSED_NOT_YET_DECODE_VERIFIED',out);
