import { spawn } from "node:child_process";
import { mkdirSync, rmSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { resolve, extname } from "node:path";
import { TARGET_FPS, FRAME_MS, DEFAULT_VIEWPORT_SIZE, MAX_CAPTURE_FRAME_SLOTS, } from "./types.js";
import { ensureFfmpeg } from "./ffmpeg.js";
import { buildH264EncoderArgs, buildIntermediateCaptureArgs } from "./encoding.js";
import { compactRawVideoLosslessly, finalizeMp4, finalizeWebm, finalizeGif, } from "./media.js";
import { ScreencastSource } from "./screencast.js";
import { moveFileSync } from "./fs.js";
const MAX_FFMPEG_STDERR_CHARS = 8_000;
export function encoderExitError(code, signal, stderr) {
    if (code === 0)
        return null;
    const detail = signal ? `signal ${signal}` : `code ${code ?? "unknown"}`;
    const context = stderr.trim();
    return new Error(`ffmpeg encoder exited with ${detail}${context ? `: ${context}` : ""}`);
}
export function frameSlotsForElapsed(elapsedMs, frameMs = FRAME_MS) {
    return Math.min(MAX_CAPTURE_FRAME_SLOTS, Math.max(1, Math.round(elapsedMs / frameMs)));
}
export function frameSlotsForClock(elapsedMs, emittedFrames, frameMs = FRAME_MS) {
    const desiredFrames = Math.floor(elapsedMs / frameMs + 1e-6);
    return Math.min(MAX_CAPTURE_FRAME_SLOTS, Math.max(0, desiredFrames - emittedFrames));
}
export class Recorder {
    outputPath = "";
    frameCount = 0;
    running = false;
    capturePromise = null;
    events = [];
    outputWidth;
    outputHeight;
    sfx;
    fps;
    frameMs;
    crf;
    captureFormat;
    captureQuality;
    preferScreenshots;
    ffmpegPath = "ffmpeg";
    ffmpegProcess = null;
    tempVideo = "";
    drainResolve = null;
    droppedFrames = 0;
    timeline = null;
    ctx = null;
    framesDir = null;
    stopResolve = null;
    stoppedPromise = null;
    screencastSource = null;
    captureError = null;
    ffmpegStderr = "";
    constructor(outputWidth = DEFAULT_VIEWPORT_SIZE, outputHeight = DEFAULT_VIEWPORT_SIZE, options) {
        this.outputWidth = outputWidth;
        this.outputHeight = outputHeight;
        this.sfx = options?.sfx;
        this.fps = options?.fps ?? TARGET_FPS;
        this.frameMs = 1000 / this.fps;
        this.crf = options?.crf ?? 18;
        this.captureFormat = options?.captureFormat ?? "jpeg";
        this.captureQuality = options?.captureQuality ?? 95;
        this.preferScreenshots = options?.preferScreenshots ?? false;
        if (options?.framesDir) {
            this.framesDir = options.framesDir;
            mkdirSync(this.framesDir, { recursive: true });
        }
    }
    setTimeline(timeline) {
        this.timeline = timeline;
    }
    getTimeline() {
        return this.timeline;
    }
    getTimelineData() {
        return this.timeline?.toJSON() ?? null;
    }
    addEvent(type) {
        if (this.running) {
            const timeMs = (this.frameCount / this.fps) * 1000;
            this.events.push({ type, timeMs });
        }
    }
    async start(client, outputPath, ctx) {
        this.ffmpegPath = await ensureFfmpeg();
        this.outputPath = outputPath;
        this.frameCount = 0;
        this.droppedFrames = 0;
        this.captureError = null;
        this.ffmpegStderr = "";
