#!/usr/bin/env python3
"""One temporary Hermes public-browser worker; JSON request on stdin, JSONL on stdout.

This is a custom test harness, not the stock Slack gateway or an OS sandbox.
The dispatcher must authenticate the Slack message and supply a dedicated, blank
yyoreel Chrome endpoint. Never supply the endpoint of a Slack login browser.

Request fields: run_id, task_id, sender_id, workspace_id, channel_id, slack_ts,
text, browser_cdp_url, allowed_hosts, runtime={api_key, provider, api_mode,
base_url, model}. Optional: max_iterations (1..24), budget_seconds (30..300),
recording_hold_seconds (0..30). Credentials travel only over the input pipe.
"""

from __future__ import annotations

import contextlib
import datetime as dt
import io
import json
import logging
import os
from pathlib import Path
import re
import sys
import threading
import time
from urllib.parse import urlsplit


ROOT = Path(__file__).resolve().parent
UPSTREAM = ROOT.parent / "upstream"
ALLOWED_TOOLS = frozenset({
    "browser_navigate", "browser_snapshot",
    "browser_scroll", "browser_back",
})
ALLOWED_SENDERS = {"U0C684PHZ5H", "U0C688SF7DZ"}
OUTPUT = sys.stdout
OUTPUT_LOCK = threading.Lock()
SECRET_VALUES: list[str] = []
IDENTITY: dict = {}


def scrub(value):
    if isinstance(value, dict):
        return {str(k): ("[redacted]" if str(k).lower() in {
            "api_key", "access_token", "refresh_token", "authorization", "cookie",
        } else scrub(v)) for k, v in value.items()}
    if isinstance(value, (list, tuple)):
        return [scrub(v) for v in value]
    if isinstance(value, str):
        for secret in SECRET_VALUES:
            value = value.replace(secret, "[redacted]")
        return re.sub(r"(?i)Bearer\s+[^\s\"']+", "Bearer [redacted]", value)
    return value


def emit(event: str, **fields):
    data = {
        "event": event, "utc": dt.datetime.now(dt.timezone.utc).isoformat(),
        "wall_time_ns": time.time_ns(), "monotonic_ns": time.monotonic_ns(),
        "pid": os.getpid(), **IDENTITY, **fields,
    }
    with OUTPUT_LOCK:
        OUTPUT.write(json.dumps(scrub(data), ensure_ascii=False, default=str) + "\n")
        OUTPUT.flush()


class DiagnosticSink(io.TextIOBase):
    """Keep library chatter out of JSONL, with explicit secret redaction."""

    def __init__(self, path: Path):
        self.handle = path.open("x", encoding="utf-8")
        self.lock = threading.Lock()
        self.pending = ""

    def write(self, value):
        with self.lock:
            self.pending += str(value)
            while "\n" in self.pending:
                line, self.pending = self.pending.split("\n", 1)
                self.handle.write(scrub(line) + "\n")
            if len(self.pending) > 1024 * 1024:
                self.pending = "[oversized diagnostic line omitted]"
            self.handle.flush()
        return len(value)

    def flush(self):
        with self.lock:
            self.handle.flush()

    def close(self):
        if not self.closed:
            super().close()
            with self.lock:
                if self.pending:
                    self.handle.write(scrub(self.pending))
                    self.pending = ""
            self.handle.close()


def safe_id(value, name):
    if not isinstance(value, str) or not re.fullmatch(r"[A-Za-z0-9_-]{1,80}", value):
        raise ValueError(f"Invalid {name}")
    return value


