    runtime = request.get("runtime") or {}
    token = runtime.get("api_key")
    if not isinstance(token, str) or not token:
        raise ValueError("runtime.api_key is required through stdin")
    SECRET_VALUES.append(token)
    if runtime.get("provider") != "openai-codex" or runtime.get("api_mode") != "codex_responses":
        raise ValueError("This harness accepts only the reviewed Codex Responses runtime")
    if runtime.get("base_url", "").rstrip("/") != "https://chatgpt.com/backend-api/codex":
        raise ValueError("Unreviewed model endpoint")
    if runtime.get("model") != "gpt-6.1-sol":
        raise ValueError("Unreviewed model")
