    clean_env = {key: os.environ[key] for key in (
        "HOME", "PATH", "SHELL", "LANG", "LC_ALL", "USER", "LOGNAME", "TMPDIR",
        "SYSTEMROOT", "COMSPEC", "PATHEXT",
    ) if key in os.environ}
    clean_env.update({
        "HERMES_HOME": str(worker_home),
        "HERMES_MANAGED_DIR": str(task_dir / "managed"),
        "HERMES_GATEWAY_LOCK_DIR": str(task_dir / "gateway-locks"),
        "HERMES_DISABLE_LAZY_INSTALLS": "1", "HERMES_STARTUP_WARMUP_TIMEOUT": "0",
        "BROWSER_CDP_URL": request["browser_cdp_url"],
        "PYTHONUNBUFFERED": "1",
