            # it is not a network firewall and does not constrain HTTP redirects.
            from tools.registry import registry
            entry = registry.get_entry("browser_navigate")
            original_navigate = entry.handler

            def bounded_navigate(arguments, **kwargs):
                target = urlsplit(arguments.get("url", ""))
                if target.scheme != "https" or target.hostname not in allowed_hosts or target.username or target.password:
                    emit("navigation_denied", url=arguments.get("url", ""))
                    return json.dumps({"error": "Navigation outside this task's approved public hosts denied"})
