// Task-local yyoreel SDK capture: no browser launches or navigation.
// Usage: node paced-capture.mjs /absolute/plan.json
// Plan: {out,tracks:[{name,port,targetId}],durationSeconds?,stopFile?,readyFile?,fps?,width?,height?}
import {readFileSync,writeFileSync,mkdirSync,existsSync,linkSync,statSync,copyFileSync} from 'node:fs';
import {join,resolve} from 'node:path';
import {connectCDP,RecordingContext,Recorder,InteractionTimeline,pause} from '/Users/tanishqpalandurkar/.npm-global/lib/node_modules/@yyopc/yyoreel/dist/core/index.js';

const plan=JSON.parse(readFileSync(process.argv[2],'utf8'));
if(plan.runDir){
 const targets=['worker-a','worker-b'].map(t=>join(plan.runDir,t,'browser-target.json'));
 const deadline=Date.now()+150000;
 while(targets.some(t=>!existsSync(t))){if(Date.now()>deadline)throw new Error('Worker target preparation timed out');await pause(200);}
 plan.tracks=targets.map((file,i)=>({...JSON.parse(readFileSync(file,'utf8')),name:['worker-A','worker-B'][i]}));
 plan.readyFile=join(plan.runDir,'recording-ready');
}
const out=resolve(plan.out),fps=plan.fps??5,width=plan.width??960,height=plan.height??650;
if(!Array.isArray(plan.tracks)||!plan.tracks.length)throw new Error('Explicit track list required');
mkdirSync(out,{recursive:true});
const tracks=[],metadata={pipeline:plan.preferScreencast?'yyoreel 0.3.3 Recorder SDK screencast; task-local maximum stream dimensions':'yyoreel 0.3.3 Recorder SDK; task-local paced CDP screenshot client',fps,width,height,tracks:[],started_utc:new Date().toISOString()};
let heartbeatTimer=null;
if(plan.diagnostic){metadata.heartbeat=[];heartbeatTimer=setInterval(()=>metadata.heartbeat.push(new Date().toISOString()),200);}
const save=()=>writeFileSync(join(out,'capture-metadata.json'),JSON.stringify(metadata,null,2));
let failure=null;
const preserve=t=>{if(typeof t.meta.temp_path==='string'&&existsSync(t.meta.temp_path)&&!existsSync(t.preservePath))linkSync(t.meta.temp_path,t.preservePath);};
const preserveTimer=setInterval(()=>{for(const t of tracks){try{preserve(t);}catch{}}},100);

try{
 for(const spec of plan.tracks){
  if(!/^[a-zA-Z0-9_-]+$/.test(spec.name))throw new Error('Invalid track name');
  if(!spec.targetId)throw new Error('Explicit verified targetId required');
  const tabs=await(await fetch(`http://127.0.0.1:${spec.port}/json/list`)).json();
  const target=tabs.find(t=>t.type==='page'&&t.id===spec.targetId);
  if(!target)throw new Error('Verified target absent: '+spec.name);
  const client=await connectCDP(target.webSocketDebuggerUrl);
  await client.Page.enable();await client.Runtime.enable();
  if(plan.preferScreencast&&target.url==='about:blank')await client.Page.bringToFront();
  await client.Emulation.setDeviceMetricsOverride({width,height,deviceScaleFactor:1,mobile:false});
  const meta={name:spec.name,port:spec.port,targetId:spec.targetId,initial_url:target.url,started_utc:new Date().toISOString(),screenshots:[]};
  if(plan.preferScreencast){meta.screencast_events=[];client.Page.screencastFrame(event=>meta.screencast_events.push({utc:new Date().toISOString(),metadata:event.metadata,base64_bytes:event.data.length}));}
  metadata.tracks.push(meta);
  let nextAt=performance.now();
  // Recorder.screenshotLoop does not pace requests at its configured FPS.
  // Pace its documented CDP capture call; underlying yyoreel encoding remains unchanged.
  const pacedClient={Runtime:client.Runtime,Page:{captureScreenshot:async args=>{
   await pause(Math.max(0,nextAt-performance.now()));
   const started=performance.now(),utc=new Date().toISOString();
