 while(plan.targetFiles.some(t=>!existsSync(t.path))){if(Date.now()>deadline)throw new Error('Gateway target preparation timed out');await pause(200);}
 plan.tracks=plan.targetFiles.map(t=>({...JSON.parse(readFileSync(t.path,'utf8')),name:t.name}));
